import { Component, OnDestroy, OnInit, TemplateRef, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Accordion, AlertMessageService, DatePickerComponent, GovBrAccordionModule, GovBrAlertMessagesModule, GovBrDatePickerModule, GovBrInputModule, GovBrModalModule, GovBrRadioModule, GovBrSelectModule, GovBrTabModule } from '@serpro/ngx-dsgovbr';
import { CalcularService } from '../../services/calcular.service';
import { CommonModule } from '@angular/common';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { environment } from '../../../environments/environment';

import { MensagemService } from '../../services/mensagem.service';
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { SimuladorCalculoPedagioResultadoComponent } from './simulador-calculo-pedagio-resultado/simulador-calculo-pedagio-resultado.component';
import { BarraBotoesComponent } from '../diversos/barra-botoes/barra-botoes.component';
import { Subscription } from 'rxjs';
import { Dispositivos } from '../../enums/dispositivos.enum';
import { DispositivoService } from '../../services/dispositivo.service';
import { DadosAbertosService } from '../../services/dados-abertos.service';

@Component({
  selector: 'simulador-calculo-pedagio',
  templateUrl: './simulador-calculo-pedagio.component.html',
  styleUrl: './simulador-calculo-pedagio.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrAlertMessagesModule,
    GovBrDatePickerModule,
    GovBrSelectModule,
    GovBrInputModule,
    GovBrTabModule,
    TooltipModule,
    GovBrRadioModule,
    GovBrModalModule,
    GovBrAccordionModule,
    MyTitleComponent,
    SimuladorCalculoPedagioResultadoComponent,
    BarraBotoesComponent
  ]
})
export class SimuladorCalculoPedagioComponent implements OnInit, OnDestroy {

  @ViewChild('datePicker') datePicker: DatePickerComponent | undefined;

  @ViewChild('tributacaoTemplate', { static: true })
  private tributacaoTemplate!: TemplateRef<any>;

  @ViewChild('adicionarTrechoTemplate', { static: true })
  private adicionarTrechoTemplate!: TemplateRef<any>;

  accordion!: Accordion;

  accordionTrechos!: Accordion;

  private readonly subscriptions: Subscription = new Subscription();

  dispositivo: string = '';

  selectValueMaxWidth: number = 60;

  dados: any = null;
  totalAliquotaAdValorem: any = null;
  totalAliquotaAdRem: any = null;
  totalTributoCalculado: any = null;
  calculadoraOutput: any;
  calculadoraInput: any;
  form!: FormGroup;
  cClassTribValues: any[] = [];
  cstValues: any[] = [];
  municipioValues: any[] = [];
  ufValues: any[] = [];
  municipioTrechoValues: any[] = [];
  ufTrechoValues: any[] = [];
  rows: any[] = [];

  header: string = '';

  constructor(
    private calcularService: CalcularService,
    private formBuilder: FormBuilder,
    private mensagemService: MensagemService,
    public alertMessageService: AlertMessageService,
    private readonly dispositivoService: DispositivoService,
    private dadosAbertosService: DadosAbertosService,
  ) { }
  ngOnDestroy(): void {
    this.mensagemService.limpar();
  }

  ngOnInit(): void {



    this.form = this.formBuilder.group({
      dataControl: [{ value: new Date(), disabled: false }, [Validators.required]],
      cstControl: [{ value: null, disabled: true }, [Validators.required]],
      cClassTribControl: [{ value: null, disabled: true }, [Validators.required]],
      valorOperacaoControl: [{ value: 200.00, disabled: false }, [Validators.required]],

      ufTrechoControl: [{ value: null, disabled: false }, [Validators.required]],
      municipioTrechoControl: [{ value: null, disabled: false }, [Validators.required]],
      extensaoControl: [{ value: 0.00, disabled: false }, [Validators.required]],

      trechos: this.createFormArray(),
    });

    this.dadosAbertosService.obterSituacoesTributariasCbsIbs(this.form.get('dataControl')?.value).subscribe({
      next: (data) => {
        for (let x of data) {
          this.cstValues = [...this.cstValues, { id: x.id, codigo: x.codigo, nome: x.nome, label: x.codigo + ' - ' + x.descricao }]
        }
        this.dadosAbertosService.obterClassificacoesTributariasCbsIbs(this.cstValues[0].id, this.form.get('dataControl')?.value).subscribe({
          next: (data) => {
            this.cClassTribValues = [];
            for (let x of data) {
              this.cClassTribValues = [...this.cClassTribValues, { codigo: x.codigo, descricao: x.descricao, label: x.codigo + ' - ' + x.descricao }]
            }
            this.form.get('cstControl')?.setValue(this.cstValues[0]);
            this.form.get('cClassTribControl')?.setValue(this.cClassTribValues[1]);
          }
        })
      }
    })
    this.dadosAbertosService.obterUfs().subscribe({
      next: (data: any[]) => {
        this.ufValues = data;
        this.ufTrechoValues = data;
        data.sort((a, b) => (a.nome > b.nome) ? 1 : ((b.nome > a.nome) ? -1 : 0))
      }
    })


    this.accordion = new Accordion();
    this.accordion.isSingle = true;
    this.accordion.type = 'positive'
    this.accordion.items = [
      {
        title: 'Tributação',
        expanded: false,
        templateRef: this.tributacaoTemplate
      }
    ]

    this.accordionTrechos = new Accordion();
    this.accordionTrechos.isSingle = true;
    this.accordionTrechos.type = 'positive'
    this.accordionTrechos.items = [
      {
        title: 'Trechos',
        expanded: true,
        templateRef: this.adicionarTrechoTemplate
      }
    ]

    this.setSubscriptions();
  }

  resetarValores() {
    this.calculadoraOutput = null;
    this.calculadoraInput = null;
  }

  limpar = () => {
    this.form.reset();
    this.resetarValores();
  }

  mostrarMensagem(tipo: string, titulo: string, mensagem: string) {
    this.mensagemService.mostrar(tipo, titulo, mensagem);
  }

  createFormArray() {
    const elements: any[] = [];
    this.rows.forEach(row => {
      elements.push(this.formBuilder.group(row));
    });
    return this.formBuilder.array(elements);
  }

  addNewRow() {
    let uf = this.form.get('ufTrechoControl')?.value;
    let municipio = this.form.get('municipioTrechoControl')?.value;
    let extensao: number = this.form.get('extensaoControl')?.value;
    if (!uf || !municipio || extensao == 0) {
      this.mostrarMensagem('Erro', 'Erro', 'Campos obrigatórios não preenchidos');
      return;
    }
    const newRow = {
      uf: uf.sigla,
      codigoMunicipio: municipio.codigo,
      nomeMunicipio: municipio.nome,
      extensao: extensao
    };
    this.rows.push(newRow);
    const trechos = this.form.get('trechos') as FormArray;
    trechos.push(this.formBuilder.group(newRow));
  }

  incluirTrecho() {
    if (this.form.get('extensaoControl')?.value == 0) {
      this.mostrarMensagem('Erro', 'Erro', 'Extensão do trecho inválida');
      return;
    }
    if (this.verificarMunicipioRepetido(this.form.get('municipioTrechoControl')?.value?.codigo)) {
      this.mostrarMensagem('Erro', 'Erro', 'Município já informado');
      return;
    }
    this.addNewRow();
  }

  excluirTrecho(index: number) {
    this.calculadoraOutput = null;
    this.rows.splice(index, 1);
    const trechos = this.form.get('trechos') as FormArray;
    trechos.removeAt(index);
  }

  calcular() {
    if (this.form.invalid) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Formulário inválido.');
      return;
    }
    if (this.rows.length == 0) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Nenhum trecho informado.');
      return;
    }
    if (this.form.get('extensaoControl')?.value == 0) {
      this.mensagemService.mostrar('Erro', 'Erro', 'Extensão do trecho inválido.');
      return;
    }
    let body = this.obterBody(this.form, this.rows);
    this.calcularService.calcularTributosPedagio(body).subscribe({
      next: (data) => {
        this.calculadoraOutput = data.body;
        this.calculadoraInput = body;
        let header = data.headers.get('x-warning-dados-simulados') || null;
        this.header = header;
        if (environment.profile === 'local') {
          this.salvarArquivo(body);
          this.salvarArquivo(this.calculadoraOutput);
        }
        this.tratarDados(this.calculadoraOutput.trechos);
        //this.totalTributoCalculado = atribuirValores(this.dados, this.calculadoraOutput);
        if (!header) {
          this.mostrarMensagem('Sucesso', 'Sucesso', 'Cálculo efetuado com sucesso');
        }
        if (header) {
          this.mensagemService.mostrar('Aviso', 'Aviso', this.obterAviso(header));
        }
      }
    });
  }

  municipiosOk: any[] = [];
  estadosOk: any[] = [];

  tratarDados(data: any[]) {
    let municipios: any[] = [];
    let estados: any[] = [];
    let municipiosComAliquotas: any[] = [];
    let estadosComAliquotas: any[] = [];
    let municipiosOk: any[] = [];
    let estadosOk: any[] = [];

    for (let x of data) {
      municipios = [...municipios, x.municipio];
      estados = [...estados, x.uf];
      municipiosComAliquotas = [...municipiosComAliquotas, { municipio: x.municipio, aliquota: x.ibsMunicipal.aliquotaEfetiva, tributo: x.ibsMunicipal.tributoCalculado }];
      estadosComAliquotas = [...estadosComAliquotas, { uf: x.uf, aliquota: x.ibsEstadual.aliquotaEfetiva, tributo: x.ibsEstadual.tributoCalculado }];
    }

    let setMunicipios = new Set(municipios);
    let setEstados = new Set(estados);
    municipios = Array.from(setMunicipios);
    estados = Array.from(setEstados);

    // Sum tributo and aliquota for each municipio
    let municipioSums = new Map();
    for (let item of municipiosComAliquotas) {
      if (!municipioSums.has(item.municipio)) {
        municipioSums.set(item.municipio, { aliquota: 0, tributo: 0 });
      }
      let current = municipioSums.get(item.municipio);
      municipioSums.set(item.municipio, {
        aliquota: current.aliquota + item.aliquota,
        tributo: current.tributo + item.tributo
      });
    }
    municipiosOk = Array.from(municipioSums.entries()).map(([municipio, sums]) => ({ municipio, ...sums }));

    // Sum tributo and aliquota for each estado
    let estadoSums = new Map();
    for (let item of estadosComAliquotas) {
      if (!estadoSums.has(item.uf)) {
        estadoSums.set(item.uf, { aliquota: 0, tributo: 0 });
      }
      let current = estadoSums.get(item.uf);
      estadoSums.set(item.uf, {
        aliquota: current.aliquota + item.aliquota,
        tributo: current.tributo + item.tributo
      });
    }
    estadosOk = Array.from(estadoSums.entries()).map(([uf, sums]) => ({ uf, ...sums }));
    this.municipiosOk = [...municipiosOk];
    this.estadosOk = [...estadosOk];
  }

  obterNomeMunicipio(codigoMunicipio: any): string | null {
    let rows: any[] = this.rows;
    for (let row of rows) {
      if (row.codigoMunicipio === codigoMunicipio) {
        return row.nomeMunicipio + ' - ' + row.uf;
      }
    }
    return null;
  }

  verificarMunicipioRepetido(codigoMunicipio: any): boolean {
    let rows: any[] = this.rows;
    for (let row of rows) {
      if (row.codigoMunicipio === codigoMunicipio) {
        return true;
      }
    }
    return false;
  }

  obterBody(form: any, rows: any[]) {
    let trechos: any[] = [];
    for (const [i, x] of rows.entries()) {
      trechos = [...trechos, { numero: i + 1, uf: x.uf, municipio: x.codigoMunicipio, extensao: x.extensao }];
    }
    let body = {
      dataHoraEmissao: this.calcularService.formatarDataParaBackend(form.get('dataControl').value),
      ufMunicipioOrigem: trechos[0].uf,
      codigoMunicipioOrigem: trechos[0].municipio,
      cst: form.get('cstControl').value.codigo,
      cClassTrib: form.get('cClassTribControl').value.codigo,
      baseCalculo: form.get('valorOperacaoControl').value,
      trechos: trechos
    };
    return body;
  }


  valorOperacaoControlChange(event: any) {
    this.resetarValores();
  }

  dataControlChange(event: any) {
    this.resetarValores();
  }

  cstControlChange(event: any) {

    this.resetarValores();

    this.form.get('cClassTribControl')?.reset();

    this.dadosAbertosService.obterClassificacoesTributariasCbsIbs(event.id, this.form.get('dataControl')?.value).subscribe({
      next: (data) => {
        this.cClassTribValues = [];
        for (let x of data) {
          this.cClassTribValues = [...this.cClassTribValues, { codigo: x.codigo, descricao: x.descricao, label: x.codigo + ' - ' + x.descricao, unidadeMedida: x.unidadeMedida }]
        }
      }
    })

  }

  cClassTribControlChange(event: any) {
    this.resetarValores();
  }

  municipioTrechoControlChange(event: any) {
    this.resetarValores();
  }

  ufTrechoControlChange(event: any) {
    this.resetarValores();
    this.dadosAbertosService.obterMunicipios(event.sigla).subscribe({
      next: (data) => {
        this.municipioTrechoValues = data;
        this.form.patchValue({
          municipioTrechoControl: ''
        })
      }
    });
  }

  extensaoControlChange(event: any) {
    this.resetarValores();
  }


  salvarArquivo(x: any) {
    var data = new Blob([JSON.stringify(x, null, 4)], { type: 'application/json;charset=utf-8' });
    var link = document.createElement('a');
    link.href = window.URL.createObjectURL(data);
    link.target = '_blank';
    link.click();
  }




  verificarDispositivo(dispositivo: string) {
    this.dispositivo = dispositivo;
    switch (dispositivo) {
      case Dispositivos.XSMALL:
        this.selectValueMaxWidth = 30;
        break;
      case Dispositivos.SMALL:
        this.selectValueMaxWidth = 50;
        break;
      case Dispositivos.MEDIUM:
        this.selectValueMaxWidth = 40;
        break;
      case Dispositivos.LARGE:
        this.selectValueMaxWidth = 60;
        break;
      case Dispositivos.XLARGE:
        this.selectValueMaxWidth = 60;
        break;
      default:
        this.selectValueMaxWidth = 60;
        break;
    }
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.verificarDispositivo(dispositivo);
      })
    );
    this.subscriptions.add(
      this.form.get('dataControl')?.valueChanges.subscribe(value => {
        this.dataControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('cstControl')?.valueChanges.subscribe(value => {
        this.cstControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('cClassTribControl')?.valueChanges.subscribe(value => {
        this.cClassTribControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('valorOperacaoControl')?.valueChanges.subscribe(value => {
        this.valorOperacaoControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('municipioTrechoControl')?.valueChanges.subscribe(value => {
        this.municipioTrechoControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('ufTrechoControl')?.valueChanges.subscribe(value => {
        this.ufTrechoControlChange(value);
      })
    );
    this.subscriptions.add(
      this.form.get('extensaoControl')?.valueChanges.subscribe(value => {
        this.extensaoControlChange(value);
      })
    );
  }

  AVISOS: { [key: string]: string } = {
    '0': '',
    '1': 'Para a data selecionada, as alíquotas da CBS e do IBS ainda não possuem valores definidos em lei. Para fins de simulação foram utilizados valores fictícios.',
    '2': 'Para a data selecionada, as alíquotas da CBS e do IBS ainda não possuem valores definidos em lei. Para fins de simulação foram utilizados valores fictícios.',
    '3': 'Para a data selecionada, as alíquotas da CBS e do IBS ainda não possuem valores definidos em lei. Para fins de simulação foram utilizados valores fictícios.',
    '4': 'Para a data selecionada, as alíquotas da CBS e do IBS ainda não possuem valores definidos em lei. Para fins de simulação foram utilizados valores fictícios.',
    '5': 'Para a data selecionada, as alíquotas da CBS e do IBS ainda não possuem valores definidos em lei. Para fins de simulação foram utilizados valores fictícios.'
  };

  obterAviso(header: any): string {

    if (!header) {
      return '';
    }
    const headerKey = String(header);
    return this.AVISOS[headerKey] || '';
  }

}


