import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { BrModalSize, GovBrModalModule } from '@serpro/ngx-dsgovbr';
import { BsModalRef, BsModalService } from 'ngx-bootstrap/modal';

@Component({
  selector: 'modal-detalhes-pedagio',
  templateUrl: './modal-detalhes-pedagio.component.html',
  styleUrl: './modal-detalhes-pedagio.component.scss',
  standalone: true,
  providers: [BsModalService],
  imports: [
    CommonModule,
    GovBrModalModule
  ]
})
export class ModalDetalhesPedagioComponent implements OnInit {

  resizeable = true;
  disabled = false;
  closeButton = true;
  size: BrModalSize = 'sm';

  detalhes?: any;
  municipiosOk?: any;
  estadosOk?: any;
  rows?: any;

  onBotaoModalClick() {
  }

  constructor(
    public bsModalService: BsModalService,
    public bsModalRef: BsModalRef,
  ) { }

  ngOnInit(): void {
  }

  obterNomeMunicipio(codigoMunicipio: any): string | null {
    let rows: any[] = this.rows;
    for (let row of rows) {
        if (row.codigoMunicipio === codigoMunicipio) {
            return row.nomeMunicipio + ' - ' + row.uf;
        }
    }
    return null;
  }

  fechar() {
    this.bsModalRef.hide();
  }

  
}
