import { Component, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { DispositivoService } from '../../../services/dispositivo.service';
import { TooltipModule } from 'ngx-bootstrap/tooltip';
import { GovBrModalModule } from '@serpro/ngx-dsgovbr';
import { BsModalService, ModalOptions } from 'ngx-bootstrap/modal';
import { ModalDetalhesPedagioComponent } from '../modal-detalhes-pedagio/modal-detalhes-pedagio.component';

@Component({
  selector: 'simulador-calculo-pedagio-resultado',
  templateUrl: './simulador-calculo-pedagio-resultado.component.html',
  styleUrl: './simulador-calculo-pedagio-resultado.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    TooltipModule,
    GovBrModalModule
  ]
})
export class SimuladorCalculoPedagioResultadoComponent implements OnInit {

  @Input() dados!: any;
  @Input() calculadoraOutput!: any;
  @Input() municipiosOk!: any;
  @Input() estadosOk!: any;
  @Input() rows!: any;
  @Input() header!: string;

  private subscriptions: Subscription = new Subscription();
  
  dispositivo: string = '';

  constructor(
    private dispositivoService: DispositivoService,
    private bsModalService: BsModalService,
  ) { }

  ngOnInit(): void {

    this.setSubscriptions();
  }
  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  teste() {
  }

    mostrarDetalhes(x: any) {
      const modalOptions: ModalOptions = {
        class: 'modal-lg',
        backdrop: true,
        ignoreBackdropClick: false,
        animated: true,
        initialState: {
          detalhes: this.calculadoraOutput,
          municipiosOk: this.municipiosOk,
          estadosOk: this.estadosOk,
          rows: this.rows
        }
      }
      this.bsModalService.show(ModalDetalhesPedagioComponent, modalOptions);
    }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.dispositivo = dispositivo;
      })
    );
  }

}
